sysauto_script.script:
(function executeScheduler() {
    function logSchedulerEvent(logLevel, message) {
        var gr = new GlideRecord('x_1784056_sixscape_log');
        gr.initialize();
        gr.log_level = logLevel;
        gr.script = "Sixscape IDcentral Scheduler";
        gr.application = "Sixscape IDC";
        gr.message = message;
        gr.insert();
    }

    try {
        logSchedulerEvent("Info", "Scheduler Initiated Successfully");
        // --- Run Profile and Device Sync ---
        new x_1784056_sixscape.ScheduleForProfileSync().syncProfiles();
        new x_1784056_sixscape.ScheduleForDeviceSync().syncDevices();-
        logSchedulerEvent("Info", "Scheduler Completed Successfully");
        gs.info("Sixscape IDcentral Scheduler ran successfully.");
    } catch (ex) {
        logSchedulerEvent("Error", "Scheduler Error: " + ex.message);
        gs.error("Sixscape IDcentral Scheduler error: " + ex.message);
        throw ex; // Optional: Rethrow to fail MID job if required
    }
})();
